//! Deterministic fuzz tests for the ClientHello parser.
//!
//! The L4 listener feeds attacker-controlled bytes into [`parse_client_hello`] on every connection,
//! so the parser must never panic, never hang, and only ever return a typed [`ParseError`] or a
//! classification. The corpus is generated by a fixed xorshift PRNG so failures are reproducible:
//! 10 000+ random buffers, 10 000+ mutated valid ClientHellos, and oversized declared lengths.
//!
//! Tier: **tier 1** (T-FUZZ-SEED-CLIENT-HELLO). The PRNG seeds and case counts are the in-file
//! constants below unless overridden by `FUZZ_SEED` (u64) and `FUZZ_CASES` (usize). Knob contract,
//! per `docs/compatibility/TESTING.md` §Fuzzing and `agents-prompts/fuzz-runner.md`:
//!
//! - **absent ⇒ silent tier 0**: with both variables unset the suite uses the constants, so a
//!   plain `cargo test` is byte-identical to the pre-tier behaviour;
//! - **present ⇒ tier 1**: the value replaces the constant, so a scheduled sweep explores a
//!   different corpus each run. Still deterministic *within* a run;
//! - **present-but-invalid ⇒ loud failure**, naming the variable and the offending value. A
//!   misconfigured sweep must never quietly degrade to tier 0 and report green.
//!
//! The resolved seed and case count are printed at the start of every run (`--nocapture` to see
//! them), and the count is what the loops actually execute.

use caddy_rs_l4::{parse_client_hello, ParseError};

// -------------------------------------------------------------------------------------------------
// Tier 1 knobs (FUZZ_SEED / FUZZ_CASES)
// -------------------------------------------------------------------------------------------------

/// Tier-0 seed for the random-buffer generator. Used when `FUZZ_SEED` is unset.
const SEED_RANDOM_BUFFERS: u64 = 0x9e37_79b9_7f4a_7c15;
/// Tier-0 seed for the mutation generator. Used when `FUZZ_SEED` is unset.
const SEED_MUTATED: u64 = 0x0123_4567_89ab_cdef;

/// Tier-0 case counts. Used when `FUZZ_CASES` is unset.
const CASES_RANDOM_BUFFERS: usize = 12_000;
const CASES_MUTATED: usize = 12_000;

/// Ceiling for `FUZZ_CASES`. The suite must stay CI-fast, so an out-of-range value is a loud error
/// rather than a slow suite.
const MAX_CASES: usize = 50_000;

/// Read a knob. `Ok(None)` when unset (the silent tier-0 path); `Ok(Some(v))` when set to a valid
/// value; `Err` naming the variable and the offending value when set to something unusable — so a
/// misconfigured sweep fails loudly instead of silently running tier 0 and reporting green.
fn knob<T>(name: &str, max: Option<T>) -> Result<Option<T>, String>
where
    T: std::str::FromStr + PartialOrd + std::fmt::Display + Copy,
{
    match std::env::var(name) {
        Err(std::env::VarError::NotPresent) => Ok(None),
        Err(err) => Err(format!("{name} is set but unreadable: {err}")),
        Ok(raw) => {
            let value = raw.parse::<T>().map_err(|_| {
                format!("{name}={raw:?} is not a valid value; unset it to run tier 0 (using the in-file constant), or pass a parseable value")
            })?;
            if let Some(max) = max {
                if value > max {
                    return Err(format!(
                        "{name}={raw:?} is out of range: must be at most {max}; unset it to run tier 0 (using the in-file constant)"
                    ));
                }
            }
            Ok(Some(value))
        }
    }
}

/// Resolved knob values for one run: the tier the run executed and the seeds/counts it used.
struct Knobs {
    seed: Option<u64>,
    cases: Option<usize>,
}

impl Knobs {
    /// Resolve both knobs from the environment, failing loudly on an invalid value.
    fn from_env() -> Result<Self, String> {
        Ok(Self {
            seed: knob::<u64>("FUZZ_SEED", None)?,
            cases: knob::<usize>("FUZZ_CASES", Some(MAX_CASES))?,
        })
    }

    /// Seed for a generator: the tier-1 `FUZZ_SEED` when set, else this generator's tier-0 constant.
    ///
    /// Offset by the generator's own constant so one `FUZZ_SEED` still yields a different stream
    /// per generator, exactly as the two tier-0 constants do.
    fn seed(&self, tier0: u64) -> u64 {
        match self.seed {
            Some(seed) => seed.wrapping_add(tier0),
            None => tier0,
        }
    }

    /// Case count for one generator, scaled to its share of the tier-0 budget.
    ///
    /// `FUZZ_CASES`, when set, is the total across the suite and is divided by the tier-0 total, so
    /// `FUZZ_CASES=50` runs a few cases per generator rather than 50 in each. Both loops here are
    /// flat (one case per iteration, no per-seed multiplier), so a generator's contribution to the
    /// suite total is exactly this value.
    fn cases(&self, tier0: usize) -> usize {
        match self.cases {
            None => tier0,
            Some(total) => {
                // At least one case, so a tiny FUZZ_CASES still exercises every generator.
                (total * tier0 / tier0_total()).max(1)
            }
        }
    }

    /// Cases this run actually executes. Each loop is flat, so this is the plain sum of the two
    /// per-generator counts — verified against the real loops by
    /// `announced_case_total_matches_the_executed_loops`.
    fn cases_total(&self) -> usize {
        self.cases(CASES_RANDOM_BUFFERS) + self.cases(CASES_MUTATED)
    }

    /// Print the resolved seed and case count once per run so the corpus is identifiable.
    fn announce(&self) {
        match (self.seed, self.cases) {
            (None, None) => println!(
                "client_hello_fuzz: tier 0 (FUZZ_SEED/FUZZ_CASES unset) — seeds [{}, {}], cases {} total",
                SEED_RANDOM_BUFFERS,
                SEED_MUTATED,
                self.cases_total()
            ),
            (seed, cases) => println!(
                "client_hello_fuzz: tier 1 — resolved FUZZ_SEED={:?}, FUZZ_CASES={:?} ({} cases total)",
                seed,
                cases,
                self.cases_total()
            ),
        }
    }
}

/// Sum of the two tier-0 case constants, used only as the ratio denominator when scaling
/// `FUZZ_CASES` across the generators.
///
/// Both loops here are flat, so this happens to equal the tier-0 executed total; the announcement
/// still goes through `cases_total` so the two cannot diverge if a loop ever gains a multiplier.
fn tier0_total() -> usize {
    CASES_RANDOM_BUFFERS + CASES_MUTATED
}

/// Resolve the knobs, announcing the resolved seed and case count for this run.
///
/// Fails with the variable name and offending value when a knob is present but invalid.
fn knobs_or_fail() -> Knobs {
    let knobs = Knobs::from_env().unwrap_or_else(|err| panic!("client_hello_fuzz: {err}"));
    knobs.announce();
    knobs
}

/// xorshift64 — deterministic, dependency-free PRNG.
fn xorshift(state: &mut u64) -> u64 {
    let mut x = *state;
    x ^= x << 13;
    x ^= x >> 7;
    x ^= x << 17;
    *state = x;
    x
}

/// Builds a complete TLS record containing a ClientHello with the given SNI/ALPN extensions.
fn client_hello(sni: Option<&str>, alpn: &[&str]) -> Vec<u8> {
    let mut extensions = Vec::new();
    if let Some(host) = sni {
        let mut names = vec![0_u8];
        names.extend_from_slice(&(host.len() as u16).to_be_bytes());
        names.extend_from_slice(host.as_bytes());
        let mut ext = Vec::new();
        ext.extend_from_slice(&(names.len() as u16).to_be_bytes());
        ext.extend_from_slice(&names);
        extensions.extend_from_slice(&0x0000_u16.to_be_bytes());
        extensions.extend_from_slice(&(ext.len() as u16).to_be_bytes());
        extensions.extend_from_slice(&ext);
    }
    if !alpn.is_empty() {
        let mut protocols = Vec::new();
        for name in alpn {
            protocols.push(name.len() as u8);
            protocols.extend_from_slice(name.as_bytes());
        }
        let mut ext = Vec::new();
        ext.extend_from_slice(&(protocols.len() as u16).to_be_bytes());
        ext.extend_from_slice(&protocols);
        extensions.extend_from_slice(&0x0010_u16.to_be_bytes());
        extensions.extend_from_slice(&(ext.len() as u16).to_be_bytes());
        extensions.extend_from_slice(&ext);
    }
    let mut body = Vec::new();
    body.extend_from_slice(&[0x03, 0x03]);
    body.extend_from_slice(&[0x11; 32]);
    body.push(0);
    body.extend_from_slice(&[0x00, 0x02, 0x13, 0x01]);
    body.extend_from_slice(&[1, 0]);
    if !extensions.is_empty() {
        body.extend_from_slice(&(extensions.len() as u16).to_be_bytes());
        body.extend_from_slice(&extensions);
    }
    let mut handshake = vec![1_u8];
    handshake.extend_from_slice(&(body.len() as u32).to_be_bytes()[1..]);
    handshake.extend_from_slice(&body);
    let mut record = vec![0x16_u8];
    record.extend_from_slice(&[0x03, 0x01]);
    record.extend_from_slice(&(handshake.len() as u16).to_be_bytes());
    record.extend_from_slice(&handshake);
    record
}

#[test]
fn random_buffers_never_panic_and_only_return_typed_errors() {
    run_random_buffers(&knobs_or_fail());
}

/// Runs the random-buffer loop and returns how many cases it executed.
fn run_random_buffers(knobs: &Knobs) -> usize {
    let cases = knobs.cases(CASES_RANDOM_BUFFERS);
    let mut state = knobs.seed(SEED_RANDOM_BUFFERS);
    let mut errors = 0_u32;
    for _ in 0..cases {
        let len = (xorshift(&mut state) % 700) as usize;
        let mut buf = Vec::with_capacity(len);
        for _ in 0..len {
            buf.push(xorshift(&mut state) as u8);
        }
        // Half the buffers start like a TLS record so the deeper record/handshake/extensions
        // parsers are exercised rather than only the protocol sniff.
        if len >= 5 && xorshift(&mut state) & 1 == 0 {
            buf[0] = 0x16;
        }
        match parse_client_hello(&buf) {
            // A random buffer may coincidentally classify as another protocol; the contract is
            // only that it never panics and never silently claims TLS without parsing one.
            Ok(_) => {}
            Err(error) => {
                errors += 1;
                assert!(!error.to_string().is_empty());
            }
        }
    }
    // The bound is expressed as a share of the run so it still holds under a small sweep; tier 0
    // (12 000 cases) keeps the original 9 000 floor.
    let floor = cases * 3 / 4;
    assert!(
        errors as usize >= floor,
        "most random buffers must be typed errors, got {errors} of {cases}"
    );
    cases
}

#[test]
fn mutated_valid_client_hellos_never_panic() {
    run_mutated(&knobs_or_fail());
}

/// Runs the mutation loop and returns how many cases it executed.
fn run_mutated(knobs: &Knobs) -> usize {
    let cases = knobs.cases(CASES_MUTATED);
    let valid = client_hello(Some("fuzz.example"), &["h2", "http/1.1"]);
    let mut state = knobs.seed(SEED_MUTATED);
    let mut errors = 0_u32;
    for _ in 0..cases {
        let mut buf = valid.clone();
        let mutations = 1 + (xorshift(&mut state) % 4) as usize;
        for _ in 0..mutations {
            let index = (xorshift(&mut state) as usize) % buf.len();
            buf[index] = xorshift(&mut state) as u8;
        }
        match parse_client_hello(&buf) {
            // A mutation can still leave a parseable record; the contract is no panic and only
            // typed errors otherwise.
            Ok(_) => {}
            Err(error) => {
                errors += 1;
                assert!(!error.to_string().is_empty());
            }
        }
    }
    assert!(errors > 0, "mutations must produce some typed errors");
    cases
}

/// The announced total must equal the number of cases the real loops execute, and a tier-1 sweep
/// must stay inside the documented cap.
///
/// The sum comes from the same `run_*` functions the `#[test]`s call, each returning its own
/// executed count, so this compares the announcement against real executions rather than
/// re-deriving the loops' shape. Both loops here are flat today; if either gains a multiplier (a
/// per-seed or nested count, as the adapter's mutation loop has) the sums diverge and this fails.
#[test]
fn announced_case_total_matches_the_executed_loops() {
    let tier0 = Knobs {
        seed: None,
        cases: None,
    };
    assert_eq!(
        tier0.cases_total(),
        CASES_RANDOM_BUFFERS + CASES_MUTATED,
        "tier-0 announcement must equal the two constants"
    );

    for total in [None, Some(1usize), Some(50), Some(1000), Some(MAX_CASES)] {
        let knobs = Knobs {
            seed: Some(1),
            cases: total,
        };
        let executed = run_random_buffers(&knobs) + run_mutated(&knobs);
        assert_eq!(
            knobs.cases_total(),
            executed,
            "announcement must equal the executed total for FUZZ_CASES={total:?}"
        );
        if total.is_some() {
            assert!(
                executed <= MAX_CASES,
                "FUZZ_CASES={total:?} must stay within the {MAX_CASES}-case cap, got {executed}"
            );
        }
    }
}

/// A present `FUZZ_CASES` must actually change the case count, and a present `FUZZ_SEED` must
/// actually change the seed. This pins the knob against a silent tier-0 fallback: if the resolver
/// ignores an env value and quietly uses the constant instead, a sweep would run tier 0 and report
/// green, which is exactly the failure the tier contract forbids.
#[test]
fn present_knobs_actually_override_the_constants() {
    let tier0 = Knobs {
        seed: None,
        cases: None,
    };
    let tier1 = Knobs {
        seed: Some(12345),
        cases: Some(50),
    };

    // FUZZ_CASES: the count must move off the tier-0 constant and off the tier-0 total.
    assert_ne!(
        tier1.cases(CASES_RANDOM_BUFFERS),
        tier0.cases(CASES_RANDOM_BUFFERS),
        "FUZZ_CASES must change the random-buffer count, not silently fall back to the constant"
    );
    assert_ne!(
        tier1.cases_total(),
        tier0.cases_total(),
        "FUZZ_CASES must change the announced total, not silently fall back to tier 0"
    );
    assert_eq!(
        tier1.cases_total(),
        50,
        "FUZZ_CASES=50 must run exactly 50 cases across the suite"
    );

    // FUZZ_SEED: the resolved seed must move off the tier-0 constant.
    assert_ne!(
        tier1.seed(SEED_RANDOM_BUFFERS),
        tier0.seed(SEED_RANDOM_BUFFERS),
        "FUZZ_SEED must change the random-buffer seed, not silently fall back to the constant"
    );
    assert_ne!(
        tier1.seed(SEED_MUTATED),
        tier0.seed(SEED_MUTATED),
        "FUZZ_SEED must change the mutation seed, not silently fall back to the constant"
    );

    // Tier 0 stays exactly the constants.
    assert_eq!(tier0.cases(CASES_RANDOM_BUFFERS), CASES_RANDOM_BUFFERS);
    assert_eq!(tier0.cases(CASES_MUTATED), CASES_MUTATED);
    assert_eq!(tier0.seed(SEED_RANDOM_BUFFERS), SEED_RANDOM_BUFFERS);
    assert_eq!(tier0.seed(SEED_MUTATED), SEED_MUTATED);
}

/// Tier 1 must actually vary the corpus between runs: two different `FUZZ_SEED` values must
/// produce different case streams, while a repeated value reproduces exactly.
#[test]
fn different_resolved_seeds_produce_different_case_streams() {
    let stream = |seed: u64| {
        let mut state = seed;
        let mut bufs = Vec::new();
        for _ in 0..16 {
            let len = (xorshift(&mut state) % 700) as usize;
            let mut buf = Vec::with_capacity(len);
            for _ in 0..len {
                buf.push(xorshift(&mut state) as u8);
            }
            bufs.push(buf);
        }
        bufs
    };
    let a = stream(1);
    let b = stream(2);
    assert_ne!(
        a, b,
        "FUZZ_SEED=1 and FUZZ_SEED=2 produced identical streams; tier 1 would be a no-op"
    );
    assert_eq!(
        a,
        stream(1),
        "the same seed must reproduce exactly (determinism within a run)"
    );

    // One FUZZ_SEED must still yield a different stream per generator, as the two tier-0
    // constants do.
    let knobs = Knobs {
        seed: Some(12345),
        cases: None,
    };
    assert_ne!(
        knobs.seed(SEED_RANDOM_BUFFERS),
        knobs.seed(SEED_MUTATED),
        "one FUZZ_SEED must still separate the generators"
    );
}

#[test]
fn oversized_declared_lengths_are_typed_errors_not_panics() {
    // Record length says 65535 bytes but the buffer holds far fewer: retryable.
    let mut record_len = client_hello(Some("x.example"), &["h2"]);
    record_len[3..5].copy_from_slice(&[0xff, 0xff]);
    assert_eq!(parse_client_hello(&record_len), Err(ParseError::Incomplete));

    // Handshake length (u24) says 16777215 bytes in a complete record: a permanent typed
    // rejection (no reassembly across records), not a retryable Incomplete.
    let mut handshake_len = client_hello(Some("x.example"), &["h2"]);
    handshake_len[6..9].copy_from_slice(&[0xff, 0xff, 0xff]);
    assert!(matches!(
        parse_client_hello(&handshake_len),
        Err(ParseError::Malformed(_))
    ));

    // A complete record too short to hold even a handshake header is also permanent.
    let mut short_record = client_hello(None, &[]);
    short_record[3..5].copy_from_slice(&[0x00, 0x03]);
    assert!(matches!(
        parse_client_hello(&short_record),
        Err(ParseError::Malformed(_))
    ));

    // A complete record whose extensions block claims 65535 bytes: permanent typed rejection.
    // Body layout: version(2) random(32) session_id_len(1)+session(0) cipher_len(2) suites(2)
    // compression_len(1) compression(1) => extensions_len starts at record(5)+hs(4)+41 = 50.
    let mut extensions_len = client_hello(Some("x.example"), &[]);
    let offset = 50;
    extensions_len[offset..offset + 2].copy_from_slice(&[0xff, 0xff]);
    assert!(matches!(
        parse_client_hello(&extensions_len),
        Err(ParseError::Malformed(_))
    ));

    // Truncated to the record header with a zero content type: typed error, no panic.
    assert_eq!(
        parse_client_hello(&[0x00, 0x03, 0x01, 0x00, 0x00]),
        Err(ParseError::BadRecordContentType(0x00))
    );
}
